const c=document.getElementById('terms').checked;
if(!c){showError('termsErr','You must accept the Terms of Service.');return false}
showError('termsErr','');return true}

function checkDuplicate(username,email){
const users=getUsers();
return users.some(u=>u.username.toLowerCase()===username.toLowerCase()||u.email.toLowerCase()===email.toLowerCase())}

